mapper.select:
select efafnd.*,
fn.Fn_Code as fnCode, fn.Fn_Name as fnName, fn.Pr_ID as prId,pr.Pr_Code as prCode,
fn.Fn_Amount as fnAmount,
fn.Fn_Receipt_Verification_Date as fnReceiptVerificationDate
from Engineering_Fund_Application_Fund_Number_Detail efafnd
left join Fund_Number_Info fn on efafnd.Fn_Id = fn.id
left join Payment_Receipt pr on fn.Pr_Id = pr.id
where efafnd.Efa_Id = #{id}
